//! A deliberately tiny XML attribute reader.
//!
//! The only XML this app reads is `appxmanifest.xml` and `MicrosoftGame.config`,
//! both machine-generated by the Microsoft GDK, and all we want from them is a
//! handful of attributes on known elements. That is narrow enough that a real
//! parser would be more dependency than it is worth, so this does exactly that
//! job and nothing else: find an element by name, read one of its attributes.
//!
//! It understands comments and single or double quoted values. It does not
//! understand namespaces, CDATA, DTDs or entity definitions, and it makes no
//! attempt to validate — anything beyond the shape above should use a real
//! parser instead.

/// Reads `attribute` from the first `<element …>` in `xml`.
pub fn attribute(xml: &str, element: &str, attribute: &str) -> Option<String> {
    let xml = strip_comments(xml);
    let body = element_body(&xml, element)?;
    attribute_in(body, attribute)
}

/// The text between an element's name and the `>` that closes its open tag.
fn element_body<'a>(xml: &'a str, element: &str) -> Option<&'a str> {
    let mut from = 0;
    while let Some(found) = xml[from..].find('<') {
        let start = from + found + 1;
        let rest = xml.get(start..)?;
        // The name must be followed by whitespace, `/` or `>`, so that
        // "Application" does not also match "ApplicationExtension".
        if let Some(after) = rest.strip_prefix(element) {
            if after
                .chars()
                .next()
                .is_some_and(|c| c.is_whitespace() || c == '>' || c == '/')
            {
                let end = after.find('>')?;
                return Some(&after[..end]);
            }
        }
        from = start;
    }
    None
}

fn attribute_in(body: &str, attribute: &str) -> Option<String> {
    let mut from = 0;
    while let Some(found) = body[from..].find(attribute) {
        let at = from + found;
        // Must start a word, so `Name` does not match `DisplayName`.
        let preceded_by_space = at == 0
            || body[..at]
                .chars()
                .next_back()
                .is_some_and(|c| c.is_whitespace());
        let after = body[at + attribute.len()..].trim_start();
        if preceded_by_space {
            if let Some(value) = after.strip_prefix('=') {
                let value = value.trim_start();
                let quote = value.chars().next()?;
                if quote == '"' || quote == '\'' {
                    let value = &value[1..];
                    let end = value.find(quote)?;
                    return Some(unescape(&value[..end]));
                }
            }
        }
        from = at + attribute.len();
    }
    None
}

/// Removes `<!-- … -->` spans.
///
/// This is not optional politeness: the GDK's `MicrosoftGame.config` template
/// documents its own schema with commented-out copies of real elements, so a
/// reader that ignored comments would happily return `"YourProjectExeName"` as
/// the executable.
fn strip_comments(xml: &str) -> String {
    if !xml.contains("<!--") {
        return xml.to_string();
    }
    let mut out = String::with_capacity(xml.len());
    let mut rest = xml;
    while let Some(start) = rest.find("<!--") {
        out.push_str(&rest[..start]);
        rest = match rest[start + 4..].find("-->") {
            Some(end) => &rest[start + 4 + end + 3..],
            // Unterminated comment: everything that follows is commented out.
            None => "",
        };
    }
    out.push_str(rest);
    out
}

fn unescape(text: &str) -> String {
    if !text.contains('&') {
        return text.to_string();
    }
    text.replace("&lt;", "<")
        .replace("&gt;", ">")
        .replace("&quot;", "\"")
        .replace("&apos;", "'")
        .replace("&amp;", "&")
}

#[cfg(test)]
mod tests {
    use super::*;

    const MANIFEST: &str = r#"<?xml version="1.0" encoding="utf-8"?>
<Package xmlns="http://schemas.microsoft.com/appx/manifest/foundation/windows10">
  <Identity Name="Microsoft.MinecraftUWP" Publisher="CN=Microsoft Corporation" Version="1.26.5203.0" ProcessorArchitecture="x64" />
  <Properties>
    <DisplayName>Minecraft for Windows</DisplayName>
  </Properties>
  <Applications>
    <Application Id="Game" Executable="Minecraft.Windows.exe" EntryPoint="Minecraft.App">
    </Application>
  </Applications>
</Package>
"#;

    #[test]
    fn reads_attributes_from_known_elements() {
        assert_eq!(
            attribute(MANIFEST, "Identity", "Name").as_deref(),
            Some("Microsoft.MinecraftUWP")
        );
        assert_eq!(
            attribute(MANIFEST, "Application", "Id").as_deref(),
            Some("Game")
        );
        assert_eq!(
            attribute(MANIFEST, "Application", "Executable").as_deref(),
            Some("Minecraft.Windows.exe")
        );
    }

    #[test]
    fn an_attribute_name_must_match_whole() {
        // "Name" must not be satisfied by "DisplayName".
        let xml = r#"<ShellVisuals PublisherDisplayName="Microsoft Studios" DefaultDisplayName="Minecraft" />"#;
        assert_eq!(
            attribute(xml, "ShellVisuals", "DefaultDisplayName").as_deref(),
            Some("Minecraft")
        );
        assert!(attribute(xml, "ShellVisuals", "Name").is_none());
    }

    #[test]
    fn an_element_name_must_match_whole() {
        let xml = r#"<ApplicationExtension Id="nope" /><Application Id="yes" />"#;
        assert_eq!(attribute(xml, "Application", "Id").as_deref(), Some("yes"));
    }

    #[test]
    fn handles_single_quotes_and_entities() {
        let xml = "<Thing label='Tom &amp; Jerry' />";
        assert_eq!(
            attribute(xml, "Thing", "label").as_deref(),
            Some("Tom & Jerry")
        );
    }

    #[test]
    fn missing_things_return_none() {
        assert!(attribute(MANIFEST, "Nonexistent", "Id").is_none());
        assert!(attribute(MANIFEST, "Identity", "Nonexistent").is_none());
        assert!(attribute("", "Identity", "Name").is_none());
        assert!(attribute("not xml at all", "Identity", "Name").is_none());
    }

    #[test]
    fn commented_out_elements_are_ignored() {
        // This is the shape the GDK's own config template ships with.
        let xml = r#"
<ExecutableList>
    <Executable Name="Minecraft.exe" TargetDeviceFamily="PC" />
    <!--          Name="YourProjectExeName" | The name of the target executable. -->
    <!-- <Executable Name="NotThisOne.exe" /> -->
</ExecutableList>"#;
        assert_eq!(
            attribute(xml, "Executable", "Name").as_deref(),
            Some("Minecraft.exe")
        );

        // And the real element must still be found when a comment comes first.
        let xml = r#"<!-- <Identity Name="Example" /> --><Identity Name="Real" />"#;
        assert_eq!(attribute(xml, "Identity", "Name").as_deref(), Some("Real"));
    }

    #[test]
    fn an_unterminated_comment_swallows_the_rest() {
        let xml = r#"<Identity Name="Real" /><!-- <Identity Name="Nope" />"#;
        assert_eq!(attribute(xml, "Identity", "Name").as_deref(), Some("Real"));
        assert!(attribute(r#"<!-- <Identity Name="Nope" />"#, "Identity", "Name").is_none());
    }

    #[test]
    fn an_unterminated_tag_does_not_hang_or_panic() {
        assert!(attribute("<Identity Name=\"x\"", "Identity", "Name").is_none());
        assert!(attribute("<<<<", "Identity", "Name").is_none());
    }
}
